/* jitlayout: prints src/runtime/jit/layout.h -- the struct offsets stencils.S needs (see `make jit-regen`).
 * jit.c static-asserts every value, so a layout change that was not regenerated fails the build. */
#include "../src/sp.h"
#include <stddef.h>
#include <stdio.h>

#define P(name, expr) printf("#define %s %zu\n", name, (size_t)(expr))

int main(void) {
    printf("/* generated by tools/jitlayout.c -- do not edit; run `make jit-regen` */\n");
    P("L_FRAME", sizeof(Frame));
    P("L_FR_FN", offsetof(Frame, fn));
    P("L_FR_PC", offsetof(Frame, pc));
    P("L_FR_BASE", offsetof(Frame, base));
    P("L_FR_KIND", offsetof(Frame, kind));
    P("L_FR_DBASE", offsetof(Frame, dbase));
    P("L_FR_UEV", offsetof(Frame, uev));
    P("L_VM_SLOTS", offsetof(VM, slots));
    P("L_VM_ILEFT", offsetof(VM, ileft));
    P("L_VM_NFRAMES", offsetof(VM, nframes));
    P("L_VM_STACK_END", offsetof(VM, stack_end));
    P("L_VM_NDR", offsetof(VM, ndr));
    P("L_VM_JCUR", offsetof(VM, jit_cur));
    P("L_VM_JRSP", offsetof(VM, jit_rsp));
    P("L_VM_SP", offsetof(VM, sp));
    P("L_VM_JNEW", offsetof(VM, jit_new));
    P("L_VM_JFMAX", offsetof(VM, jit_fmax));
    P("L_INST_CLS", offsetof(SInstance, cls));
    P("L_INST_SLOTS", offsetof(SInstance, slots));
    P("L_SFUNC_PROTO", offsetof(SFunc, proto));
    P("L_SFUNC_UP", offsetof(SFunc, up));
    P("L_CELL_V", offsetof(SCell, v));
    P("L_PROTO_JUNIT", offsetof(Proto, junit));
    P("L_JU_ENTRY", offsetof(JitUnit, entry));
    P("L_JU_KT", offsetof(JitUnit, kt));
    P("L_JU_CODE", offsetof(JitUnit, code));
    P("L_JU_NPARAMS", offsetof(JitUnit, nparams));
    P("L_JU_NLOCALS", offsetof(JitUnit, nlocals));
    P("L_JU_PROTO", offsetof(JitUnit, proto));
    P("L_PROTO_CODE", offsetof(Proto, code));
    P("L_JU_NEED", offsetof(JitUnit, need));
    P("L_CLS_NF", offsetof(SClass, nfields));
    P("L_CLS_DFLT", offsetof(SClass, dflt));
    P("L_INST_NSLOTS", offsetof(SInstance, nslots));
    P("L_VM_BYTES", offsetof(VM, bytes));
    P("L_VM_GCNEXT", offsetof(VM, gc_next));
    P("L_VM_MAXHEAP", offsetof(VM, lim) + offsetof(Limits, max_heap_bytes));
    P("L_VM_OBJS", offsetof(VM, objs));
    P("L_VM_NEXTID", offsetof(VM, next_id));
    P("L_VM_POOLFREE", offsetof(VM, pool_free));
    return 0;
}
